import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'
import { cache } from 'react'
import type { Database } from './types'

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

export interface AuthenticatedUser {
  user: Database['public']['Tables']['profiles']['Row'] & { authId: string }
  studioId: string
  role: StudioRole
}


/**
 * Server Supabase client for Server Components, API Route Handlers, and Server Actions.
 *
 * Uses the anon key + user session cookies.
 * RLS policies apply based on the authenticated user.
 *
 * IMPORTANT: cookies() is async in Next.js 16 — must be awaited.
 */
export async function createClient() {
  const cookieStore = await cookies()

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // setAll called from a Server Component — cookies cannot be set
            // middleware handles session refresh
          }
        },
      },
    }
  )
}

/**
 * Cached helper that validates the session and returns the authenticated user
 * together with their primary studio context.
 *
 * Wrapped in React cache() so repeated calls within the same render tree
 * (e.g. layout + page) are deduplicated — only one round-trip per request.
 *
 * Returns null when the user is not authenticated or has no studio membership.
 */
export const getAuthenticatedUser = cache(async (): Promise<AuthenticatedUser | null> => {
  const supabase = await createClient()
  const { data: { user }, error: authError } = await supabase.auth.getUser()

  if (authError || !user) return null

  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('id, email, full_name, avatar_url, is_platform_admin, created_at, updated_at')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('studio_id, role')
      .eq('user_id', user.id)
      .is('deactivated_at', null)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  if (profileResult.error || !profileResult.data) return null
  if (memberResult.error || !memberResult.data) return null

  return {
    user: { ...profileResult.data, authId: user.id },
    studioId: memberResult.data.studio_id,
    role: memberResult.data.role,
  }
})

/**
 * Service-role Supabase client for webhook handlers and admin operations.
 *
 * Bypasses RLS. NEVER expose to client. Only use server-side.
 */
export function createServiceRoleClient() {
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!serviceRoleKey) {
    throw new Error('SUPABASE_SERVICE_ROLE_KEY is not set')
  }

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    serviceRoleKey,
    {
      cookies: {
        getAll() {
          return []
        },
        setAll() {
          // No-op for service role — no session cookies
        },
      },
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  )
}
import { createBrowserClient } from '@supabase/ssr'
import type { Database } from './types'

/**
 * Browser Supabase client for use in Client Components only.
 *
 * Never import this in Server Components, API routes, or Server Actions.
 * Use lib/supabase/server.ts for those.
 */
export function createClient() {
  return createBrowserClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  )
}

import pino from 'pino'

/**
 * Structured pino logger.
 *
 * In production (Railway), outputs JSON that Railway aggregates and makes
 * searchable. In development, pino-pretty formats the output for readability.
 *
 * NEVER use console.log in production code — ESLint will block it.
 */
export const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  formatters: {
    level: (label) => ({ level: label }),
  },
  base: {
    env: process.env.NEXT_PUBLIC_APP_ENV ?? 'development',
    service: 'inkos-web',
    version: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
  },
  redact: {
    paths: [
      'req.headers.authorization',
      'req.headers.cookie',
      '*.password',
      '*.token',
      '*.api_key',
      '*.apiKey',
      '*.secret',
      '*.webhook_key',
    ],
    censor: '[REDACTED]',
  },
  timestamp: pino.stdTimeFunctions.isoTime,
  ...(process.env.NODE_ENV === 'development' && {
    transport: {
      target: 'pino-pretty',
      options: {
        colorize: true,
        translateTime: 'HH:MM:ss',
        ignore: 'pid,hostname',
      },
    },
  }),
})

/**
 * Create a child logger with request-scoped context.
 */
export function requestLogger(requestId: string) {
  return logger.child({ requestId })
}
import type { Json } from './supabase/types'

/**
 * Audit log helper.
 *
 * Writes to the audit_log table via the service-role client (bypasses RLS).
 * Every admin action, billing event, and sensitive data access should be logged here.
 *
 * Failures are logged but never throw — audit failures must not break the main flow.
 */
export async function logAuditAction(
  actorId: string | null,
  action: string,
  target: { type: string; id: string } | null,
  details: Json | null,
  studioId: string | null = null
): Promise<void> {
  try {
    // Lazy import to avoid circular deps and to keep this callable from edge runtimes
    const { createServiceRoleClient } = await import('./supabase/server')
    const supabase = createServiceRoleClient()

    await supabase.from('audit_log').insert({
      actor_id: actorId,
      action,
      target_type: target?.type ?? null,
      target_id: target?.id ?? null,
      studio_id: studioId,
      details,
    })

