import { useState } from 'react'
import { MessageSquare } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'

/**
 * S17 — Polished coming-soon empty state for /messages.
 * "Notify me" posts to /api/feature-interest (feature='messages').
 */
export function MessagesComingSoon() {
  const [loading, setLoading] = useState(false)
  const [notified, setNotified] = useState(false)

  async function handleNotify() {
    setLoading(true)
    try {
      await fetch('/api/feature-interest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ feature: 'messages' }),
      })
      setNotified(true)
      toast.success("We'll let you know when Messages ships")
    } catch {
      toast.error('Something went wrong. Try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex min-h-[60vh] flex-col items-center justify-center px-6 text-center">
      <div className="mb-6 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10">
        <MessageSquare className="h-8 w-8 text-primary" aria-hidden="true" />
      </div>
      <h1 className="mb-2 text-2xl font-bold tracking-tight text-foreground">
        Client messaging is coming soon
      </h1>
      <p className="mb-1 max-w-md text-sm text-muted-foreground">
        Threaded SMS + email chat with clients — track every conversation in one inbox.
      </p>
      <p className="mb-8 text-xs text-muted-foreground/60">
        Coming in Sprint S19
      </p>
      {notified ? (
        <p className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-4 py-2 text-sm font-medium text-emerald-600 dark:text-emerald-400">
          You&apos;re on the list
        </p>
      ) : (
        <Button
          variant="outline"
          onClick={() => void handleNotify()}
          disabled={loading}
        >
          {loading ? 'Saving...' : 'Notify me when it ships'}
        </Button>
      )}
    </div>
  )
}
'use client'
import { useEffect, useState } from 'react'

/**
 * Returns true when window.innerWidth < breakpoint.
 * Starts false (SSR-safe) and hydrates on mount.
 */
export function useIsMobile(breakpoint = 768): boolean {
  const [isMobile, setIsMobile] = useState(false)

  useEffect(() => {
    function check() {
      setIsMobile(window.innerWidth < breakpoint)
    }
    check()
    window.addEventListener('resize', check, { passive: true })
    return () => window.removeEventListener('resize', check)
  }, [breakpoint])

  return isMobile
}

