input.content:
/**
 * Twilio SMS client — thin wrapper around the Twilio Node.js SDK.
 *
 * All functions are server-only. Never import from client components.
 *
 * Graceful degradation: if TWILIO_ACCOUNT_SID / TWILIO_AUTH_TOKEN / TWILIO_PHONE_NUMBER
 * are absent, getTwilioClient() throws TwilioNotConfiguredError. Callers should catch
 * this and mark the communication as failed with a clear error message.
 */

import crypto from 'node:crypto'
import { Twilio } from 'twilio'
import { logger } from '@/lib/logger'

// ─── Error class ─────────────────────────────────────────────────────────────

export class TwilioNotConfiguredError extends Error {
  constructor() {
    super('Twilio is not configured: TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, and TWILIO_PHONE_NUMBER must all be set.')
    this.name = 'TwilioNotConfiguredError'
  }
}

// ─── Lazy singleton client ────────────────────────────────────────────────────

let _twilioClient: Twilio | null = null

export function getTwilioClient(): Twilio {
  const sid = process.env.TWILIO_ACCOUNT_SID
  const token = process.env.TWILIO_AUTH_TOKEN
  const from = process.env.TWILIO_PHONE_NUMBER

  if (!sid || !token || !from) {
    throw new TwilioNotConfiguredError()
  }

  if (!_twilioClient) {
    _twilioClient = new Twilio(sid, token)
  }

  return _twilioClient
}

// ─── Send SMS ─────────────────────────────────────────────────────────────────

export interface SendSmsParams {
  to: string           // E.164 phone number
  body: string
  mediaUrls?: string[] // MMS — image URLs (max 10 for Twilio MMS)
}

export interface SendSmsResult {
  sid: string
  status: string
}

export async function sendSms(params: SendSmsParams): Promise<SendSmsResult> {
  const client = getTwilioClient()
  const from = process.env.TWILIO_PHONE_NUMBER as string

  const payload: {
    from: string
    to: string
    body: string
    mediaUrl?: string[]
  } = {
    from,
    to: params.to,
    body: params.body,
  }

  if (params.mediaUrls && params.mediaUrls.length > 0) {
    payload.mediaUrl = params.mediaUrls
  }

  const message = await client.messages.create(payload)

  logger.info({ sid: message.sid, to: params.to, status: message.status }, 'sms: sent via Twilio')

  return { sid: message.sid, status: message.status }
}

// ─── Webhook signature verification ──────────────────────────────────────────
// Twilio signs every webhook with HMAC-SHA1 over the URL + sorted POST params.
// We use timingSafeEqual to prevent timing attacks.

export function verifyTwilioSignature(
  url: string,
  params: Record<string, string>,
  signature: string,
  authToken: string,
): boolean {
  if (!signature) return false

  // Build the string to sign: URL + sorted key/value pairs
  const sortedKeys = Object.keys(params).sort()
  const paramString = sortedKeys.map((k) => `${k}${params[k]}`).join('')
  const stringToSign = url + paramString

  const hmac = crypto.createHmac('sha1', authToken)
  hmac.update(stringToSign)
  const expected = hmac.digest('base64')

  // Constant-time comparison
  const expectedBuf = Buffer.from(expected)
  const signatureBuf = Buffer.from(signature)

  if (expectedBuf.length !== signatureBuf.length) {
    return false
  }

  return crypto.timingSafeEqual(expectedBuf, signatureBuf)
}

/**
 * Messaging send pipeline — higher-level helpers that orchestrate:
 *  1. Client phone/email validation
 *  2. Conversation upsert (find_or_create_conversation RPC)
 *  3. client_communications row insert (status = 'queued')
 *  4. BullMQ job enqueue (send-sms | send-email)
 *
 * Returns { ok, commId } on success; { ok: false, error } on validation failure.
 * Never throws — callers get a typed result.
 */

import { createServiceRoleClient } from '@/lib/supabase/server'
import { enqueueJob } from '@/lib/queue'
import { logger } from '@/lib/logger'
import { TwilioNotConfiguredError } from '@/lib/sms/twilio'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface SendSmsParams {
  studioId: string
  clientId: string
  body: string
  bookingId?: string
  projectId?: string
}

export interface SendEmailParams {
  studioId: string
  clientId: string
  subject: string
  body: string
  template?: string
  templateData?: Record<string, unknown>
  bookingId?: string
}

export interface SendResult {
  ok: boolean
  commId?: string
  error?: string
}

// ─── Resolve client phone ─────────────────────────────────────────────────────

async function resolveClientPhone(
  studioId: string,
  clientId: string,
): Promise<{ phone: string } | { error: string }> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase
    .from('clients')
    .select('phone')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    return { error: 'Client not found' }
  }

  if (!data.phone) {
    return { error: 'Client has no phone number on file' }
  }

  return { phone: data.phone }
}

// ─── Resolve client email ─────────────────────────────────────────────────────

async function resolveClientEmail(
  studioId: string,
  clientId: string,
): Promise<{ email: string } | { error: string }> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase
    .from('clients')
    .select('email')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    return { error: 'Client not found' }
  }

  if (!data.email) {
    return { error: 'Client has no email address on file' }
  }

  return { email: data.email }
}

// ─── Upsert conversation ──────────────────────────────────────────────────────

async function upsertConversation(
  studioId: string,
  channel: 'sms' | 'email',
  externalIdentifier: string,
  clientId: string,
): Promise<string> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase.rpc('find_or_create_conversation', {
    p_studio_id: studioId,
    p_channel: channel,
    p_external_identifier: externalIdentifier,
    p_client_id: clientId,
  })

  if (error || !data) {
    logger.error({ error, studioId, channel, externalIdentifier }, 'messaging: find_or_create_conversation failed')
    throw new Error('Failed to create conversation')
  }

  return data as string
}

// ─── sendSmsToClient ──────────────────────────────────────────────────────────

export async function sendSmsToClient(
  params: SendSmsParams,
  _userId: string,
): Promise<SendResult> {
  const { studioId, clientId, body, bookingId } = params

  // Resolve phone
  const phoneResult = await resolveClientPhone(studioId, clientId)
  if ('error' in phoneResult) {
    return { ok: false, error: phoneResult.error }
  }

  // Upsert conversation
  let conversationId: string
  try {
    conversationId = await upsertConversation(studioId, 'sms', phoneResult.phone, clientId)
  } catch (err) {
    return { ok: false, error: 'Failed to create or find conversation' }
  }

  const supabase = createServiceRoleClient()

  // Insert comm row (status = queued)
  const { data: comm, error: insertError } = await supabase
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      booking_id: bookingId ?? null,
      conversation_id: conversationId,
      channel: 'sms',
      direction: 'outbound',
      body,
      status: 'queued',
      metadata: {},
    })
    .select('id')
    .single()

  if (insertError || !comm) {
    logger.error({ err: insertError }, 'messaging: failed to insert sms comm row')
    return { ok: false, error: 'Failed to queue SMS' }
  }

  // Check if Twilio is configured; if not, mark failed immediately
  const twilioConfigured =
    !!process.env.TWILIO_ACCOUNT_SID &&
    !!process.env.TWILIO_AUTH_TOKEN &&
    !!process.env.TWILIO_PHONE_NUMBER

  if (!twilioConfigured) {
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: TwilioNotConfiguredError.name })
      .eq('id', comm.id)

    return {
      ok: false,
      commId: comm.id,
      error: 'SMS not configured: set TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_PHONE_NUMBER',
    }
  }

  // Enqueue BullMQ job
  await enqueueJob('send-sms', { commId: comm.id, studioId })

  return { ok: true, commId: comm.id }
}

// ─── sendEmailToClient ────────────────────────────────────────────────────────

export async function sendEmailToClient(
  params: SendEmailParams,
  _userId: string,
): Promise<SendResult> {
  const { studioId, clientId, subject, body, bookingId } = params

  // Resolve email
  const emailResult = await resolveClientEmail(studioId, clientId)
  if ('error' in emailResult) {
    return { ok: false, error: emailResult.error }
  }

  // Upsert conversation
  let conversationId: string
  try {
    conversationId = await upsertConversation(studioId, 'email', emailResult.email, clientId)
  } catch (err) {
    return { ok: false, error: 'Failed to create or find conversation' }
  }

  const supabase = createServiceRoleClient()

  // Insert comm row (status = queued)
  const { data: comm, error: insertError } = await supabase
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      booking_id: bookingId ?? null,
      conversation_id: conversationId,
      channel: 'email',
      direction: 'outbound',
      subject,
      body,
      status: 'queued',
      metadata: {},
    })
    .select('id')
    .single()

  if (insertError || !comm) {
    logger.error({ err: insertError }, 'messaging: failed to insert email comm row')
    return { ok: false, error: 'Failed to queue email' }
  }

  // Check if Resend is configured
  if (!process.env.RESEND_API_KEY) {
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'RESEND_API_KEY not set' })
      .eq('id', comm.id)

    return {
      ok: false,
      commId: comm.id,
      error: 'Email not configured: set RESEND_API_KEY',
    }
  }

  // Enqueue existing send-email job
  await enqueueJob('send-email', {
    to: emailResult.email,
    template: params.template ?? 'custom_message',
    data: {
      subject,
      body,
      commId: comm.id,
      studioId,
      ...(params.templateData ?? {}),
    },
  })

  return { ok: true, commId: comm.id }
}

/**
 * Messaging queries — server-side only (Server Components + Server Actions).
 *
 * All queries enforce studio_id scoping.
 * Uses the authenticated (anon key + session) client — RLS enforces access.
 */

import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { Conversation, ConversationChannel } from '@/lib/supabase/types'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ClientSummary {
  id: string
  first_name: string
  last_name: string | null
  email: string | null
  phone: string | null
  avatar_url: string | null
  total_spent_cents: number
  total_sessions: number
}

export interface ConversationWithClient extends Conversation {
  client: ClientSummary | null
}

export interface ConversationMessage {
  id: string
  conversation_id: string | null
  channel: 'email' | 'sms' | 'whatsapp' | 'in_app'
  direction: 'outbound' | 'inbound'
  subject: string | null
  body: string
  status: 'queued' | 'sent' | 'delivered' | 'opened' | 'clicked' | 'failed' | 'bounced'
  sent_at: string | null
  delivered_at: string | null
  opened_at: string | null
  error: string | null
  provider_message_id: string | null
  metadata: Record<string, unknown>
  created_at: string
  updated_at: string
}

export interface ListConversationsFilters {
  channel?: ConversationChannel
  unreadOnly?: boolean
  assignedToMe?: boolean
  search?: string
  archived?: boolean
  limit?: number
  offset?: number
}

export interface ListConversationsResult {
  conversations: ConversationWithClient[]
  total: number
}

// ─── listConversations ────────────────────────────────────────────────────────

export async function listConversations(
  studioId: string,
  filters: ListConversationsFilters = {},
): Promise<ListConversationsResult> {
  const supabase = await createClient()
  const limit = filters.limit ?? 50
  const offset = filters.offset ?? 0

  let query = supabase
    .from('conversations')
    .select(
      `
      *,
      client:clients (
        id, first_name, last_name, email, phone,
        total_spent_cents, total_sessions
      )
    `,
      { count: 'exact' },
    )
    .eq('studio_id', studioId)
    .order('last_message_at', { ascending: false, nullsFirst: false })
    .range(offset, offset + limit - 1)

  // Archived / active filter
  if (filters.archived === true) {
    query = query.not('archived_at', 'is', null)
  } else {
    query = query.is('archived_at', null)
  }

  if (filters.channel) {
    query = query.eq('channel', filters.channel)
  }

  if (filters.unreadOnly) {
    query = query.gt('unread_count', 0)
  }

  if (filters.search) {
    // Search against display_name or external_identifier
    query = query.or(
      `display_name.ilike.%${filters.search}%,external_identifier.ilike.%${filters.search}%`,
    )
  }

  const { data, error, count } = await query

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: listConversations failed')
    return { conversations: [], total: 0 }
  }

  return {
    conversations: (data ?? []) as ConversationWithClient[],
    total: count ?? 0,
  }
}

// ─── getConversation ──────────────────────────────────────────────────────────

export async function getConversation(
  studioId: string,
  conversationId: string,
): Promise<ConversationWithClient | null> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('conversations')
    .select(
      `
      *,
      client:clients (
        id, first_name, last_name, email, phone,
        total_spent_cents, total_sessions
      )
    `,
    )
    .eq('id', conversationId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    if (error?.code !== 'PGRST116') {
      logger.error({ err: error, conversationId }, 'messaging: getConversation failed')
    }
    return null
  }

  return data as ConversationWithClient
}

// ─── getConversationMessages ──────────────────────────────────────────────────

export async function getConversationMessages(
  studioId: string,
  conversationId: string,
  opts: { limit?: number; before?: string } = {},
): Promise<ConversationMessage[]> {
  const supabase = await createClient()
  const limit = opts.limit ?? 50

  let query = supabase
    .from('client_communications')
    .select('id, conversation_id, channel, direction, subject, body, status, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, created_at, updated_at')
    .eq('studio_id', studioId)
    .eq('conversation_id', conversationId)
    .order('created_at', { ascending: false })
    .limit(limit)

  if (opts.before) {
    query = query.lt('created_at', opts.before)
  }

  const { data, error } = await query

  if (error) {
    logger.error({ err: error, conversationId }, 'messaging: getConversationMessages failed')
    return []
  }

  // Return oldest-first for rendering (reverse the DESC query result)
  return ((data ?? []) as ConversationMessage[]).reverse()
}

// ─── searchMessages ───────────────────────────────────────────────────────────

export async function searchMessages(
  studioId: string,
  query: string,
): Promise<ConversationMessage[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('client_communications')
    .select('id, conversation_id, channel, direction, subject, body, status, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, created_at, updated_at')
    .eq('studio_id', studioId)
    .or(`body.ilike.%${query}%,subject.ilike.%${query}%`)
    .order('created_at', { ascending: false })
    .limit(50)

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: searchMessages failed')
    return []
  }

  return (data ?? []) as ConversationMessage[]
}

// ─── getUnreadConversationCount ───────────────────────────────────────────────

export async function getUnreadConversationCount(studioId: string): Promise<number> {
  const supabase = await createClient()

  const { count, error } = await supabase
    .from('conversations')
    .select('id', { count: 'exact', head: true })
    .eq('studio_id', studioId)
    .gt('unread_count', 0)
    .is('archived_at', null)

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: getUnreadConversationCount failed')
    return 0
  }

  return count ?? 0
}

// ─── getClientBookingsSummary ─────────────────────────────────────────────────
// Used by ClientContextCard to show quick stats

export interface ClientBookingSummary {
  id: string
  scheduled_at: string | null
  status: string
  service_name: string | null
  price_cents: number
}

export async function getClientBookingsSummary(
  studioId: string,
  clientId: string,
  limit = 3,
): Promise<ClientBookingSummary[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('bookings')
    .select('id, scheduled_at, status, price_cents, services(name)')
    .eq('studio_id', studioId)
    .eq('client_id', clientId)
    .order('scheduled_at', { ascending: false })
    .limit(limit)

  if (error) {
    logger.error({ err: error, clientId }, 'messaging: getClientBookingsSummary failed')
    return []
  }

  return (data ?? []).map((b) => ({
    id: b.id,
    scheduled_at: b.scheduled_at,
    status: b.status,
    price_cents: b.price_cents,
    service_name: Array.isArray(b.services)
      ? (b.services[0] as { name: string } | undefined)?.name ?? null
      : (b.services as { name: string } | null)?.name ?? null,
  }))
}

/**
 * Messaging mutations — server-side only.
 *
 * Each function takes studioId to ensure all mutations are scoped.
 * Uses authenticated client — RLS enforces write access.
 */

import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

// ─── markConversationRead ─────────────────────────────────────────────────────

export async function markConversationRead(
  studioId: string,
  conversationId: string,
): Promise<void> {
  const supabase = await createClient()

  // Verify studio ownership before calling RPC
  const { data: conv } = await supabase
    .from('conversations')
    .select('id, studio_id')
    .eq('id', conversationId)
    .eq('studio_id', studioId)
    .single()

  if (!conv) {
    logger.warn({ conversationId, studioId }, 'messaging: markConversationRead — not found or wrong studio')
    return
  }

  const { error } = await supabase.rpc('mark_conversation_read', {
    p_conversation_id: conversationId,
  })

  if (error) {
    logger.error({ err: error, conversationId }, 'messaging: markConversationRead RPC failed')
  }
}

// ─── assignConversation ───────────────────────────────────────────────────────

export async function assignConversation(
  studioId: string,
  conversationId: string,
  userId: string | null,
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('conversations')
    .update({ assigned_to: userId })
    .eq('id', conversationId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, conversationId, userId }, 'messaging: assignConversation failed')
    throw new Error('Failed to assign conversation')
  }
}

// ─── archiveConversation ──────────────────────────────────────────────────────

export async function archiveConversation(
  studioId: string,
  conversationId: string,
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('conversations')
    .update({ archived_at: new Date().toISOString() })
    .eq('id', conversationId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, conversationId }, 'messaging: archiveConversation failed')
    throw new Error('Failed to archive conversation')
  }
}

// ─── unarchiveConversation ────────────────────────────────────────────────────

export async function unarchiveConversation(
  studioId: string,
  conversationId: string,
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('conversations')
    .update({ archived_at: null })
    .eq('id', conversationId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, conversationId }, 'messaging: unarchiveConversation failed')
    throw new Error('Failed to unarchive conversation')
  }
}

// ─── starConversation ─────────────────────────────────────────────────────────

export async function starConversation(
  studioId: string,
  conversationId: string,
  starred: boolean,
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('conversations')
    .update({ starred })
    .eq('id', conversationId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, conversationId, starred }, 'messaging: starConversation failed')
    throw new Error('Failed to star/unstar conversation')
  }
}

// ─── linkConversationToClient ─────────────────────────────────────────────────

export async function linkConversationToClient(
  studioId: string,
  conversationId: string,
  clientId: string,
): Promise<void> {
  const supabase = await createClient()

  // Verify client belongs to this studio
  const { data: client } = await supabase
    .from('clients')
    .select('id')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (!client) {
    throw new Error('Client not found in this studio')
  }

  const { error } = await supabase
    .from('conversations')
    .update({ client_id: clientId })
    .eq('id', conversationId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, conversationId, clientId }, 'messaging: linkConversationToClient failed')
    throw new Error('Failed to link client to conversation')
  }
}

/**
 * Twilio webhook handler — handles two event types:
 *  1. Inbound SMS (From + Body present, no MessageStatus)
 *  2. Delivery status update (MessageSid + MessageStatus present)
 *
 * Security: All requests must pass Twilio HMAC-SHA1 signature verification.
 * Returns 200 always (Twilio retries on non-200). Errors are logged, never thrown.
 *
 * Note: uses service-role client because this is a webhook (no session cookie).
 * Studio routing: match To number against studios.twilio_phone_number column.
 * If that column doesn't exist yet, falls back to TWILIO_FALLBACK_STUDIO_ID env var.
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { verifyTwilioSignature } from '@/lib/sms/twilio'
import { logger } from '@/lib/logger'

// Twilio status → our status mapping
const STATUS_MAP: Record<string, 'queued' | 'sent' | 'delivered' | 'failed'> = {
  queued: 'queued',
  sending: 'queued',
  sent: 'sent',
  delivered: 'delivered',
  undelivered: 'failed',
  failed: 'failed',
  read: 'delivered',
}

// ─── POST /api/webhooks/twilio ────────────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  // Twilio sends application/x-www-form-urlencoded
  let params: Record<string, string>
  try {
    const text = await request.text()
    params = Object.fromEntries(new URLSearchParams(text))
  } catch (err) {
    logger.error({ err }, 'twilio-webhook: failed to parse body')
    return NextResponse.json({ error: 'Bad request' }, { status: 400 })
  }

  // ── Signature verification ──────────────────────────────────────────────────
  const authToken = process.env.TWILIO_WEBHOOK_AUTH_TOKEN ?? process.env.TWILIO_AUTH_TOKEN

  if (!authToken) {
    logger.error({}, 'twilio-webhook: TWILIO_WEBHOOK_AUTH_TOKEN not set — rejecting request')
    return NextResponse.json({ error: 'Webhook not configured' }, { status: 200 })
  }

  const signature = request.headers.get('x-twilio-signature') ?? ''
  // Use the full URL for signature verification
  const webhookUrl =
    process.env.NEXT_PUBLIC_APP_URL
      ? `${process.env.NEXT_PUBLIC_APP_URL}/api/webhooks/twilio`
      : `https://${request.headers.get('host') ?? 'localhost'}/api/webhooks/twilio`

  const isValid = verifyTwilioSignature(webhookUrl, params, signature, authToken)

  if (!isValid) {
    logger.warn({ signature: '[REDACTED]' }, 'twilio-webhook: invalid signature — rejecting')
    return NextResponse.json({ error: 'Invalid signature' }, { status: 403 })
  }

  const supabase = createServiceRoleClient()

  const messageSid = params['MessageSid'] ?? ''
  const messageStatus = params['MessageStatus'] ?? ''
  const from = params['From'] ?? ''
  const to = params['To'] ?? ''
  const body = params['Body'] ?? ''

  // Determine if this is an inbound message or a status callback
  const isStatusCallback = Boolean(messageSid && messageStatus && !body && !from)
  const isInbound = Boolean(from && body && !messageStatus)

  // ── Case 1: Delivery status update ─────────────────────────────────────────
  if (isStatusCallback || (messageSid && messageStatus)) {
    await handleStatusUpdate(supabase, messageSid, messageStatus, params)
    return new NextResponse(null, { status: 200 })
  }

  // ── Case 2: Inbound message ─────────────────────────────────────────────────
  if (isInbound) {
    await handleInboundSms(supabase, { from, to, body, messageSid, params })
    return new NextResponse(null, { status: 200 })
  }

  logger.warn({ params: { MessageSid: messageSid, MessageStatus: messageStatus } }, 'twilio-webhook: unrecognised payload shape')
  return new NextResponse(null, { status: 200 })
}

// ─── handleStatusUpdate ───────────────────────────────────────────────────────

async function handleStatusUpdate(
  supabase: ReturnType<typeof createServiceRoleClient>,
  messageSid: string,
  messageStatus: string,
  _params: Record<string, string>,
): Promise<void> {
  if (!messageSid) return

  const mappedStatus = STATUS_MAP[messageStatus] ?? 'sent'

  const updateData: Record<string, string | null> = {
    status: mappedStatus,
  }

  if (messageStatus === 'delivered') {
    updateData['delivered_at'] = new Date().toISOString()
  }

  const { error } = await supabase
    .from('client_communications')
    .update(updateData)
    .eq('provider_message_id', messageSid)

  if (error) {
    logger.error({ err: error, messageSid, messageStatus }, 'twilio-webhook: status update failed')
  } else {
    logger.info({ messageSid, mappedStatus }, 'twilio-webhook: status updated')
  }
}

// ─── handleInboundSms ─────────────────────────────────────────────────────────

async function handleInboundSms(
  supabase: ReturnType<typeof createServiceRoleClient>,
  msg: { from: string; to: string; body: string; messageSid: string; params: Record<string, string> },
): Promise<void> {
  const { from, to, body, messageSid, params } = msg

  // ── 1. Resolve studio from the "To" number ──────────────────────────────────
  // Try studios.twilio_phone_number column first.
  // Falls back to TWILIO_FALLBACK_STUDIO_ID if column doesn't exist yet.
  let studioId: string | null = null

  try {
    // Cast to unknown first to handle the case where twilio_phone_number column
    // may not yet be in the DB (migration pending). This is a best-effort lookup.
    const { data: studio } = await (supabase as unknown as {
      from: (table: string) => {
        select: (col: string) => {
          eq: (col: string, val: string) => {
            limit: (n: number) => {
              single: () => Promise<{ data: { id: string } | null; error: unknown }>
            }
          }
        }
      }
    })
      .from('studios')
      .select('id')
      .eq('twilio_phone_number', to)
      .limit(1)
      .single()

    studioId = (studio as { id: string } | null)?.id ?? null
  } catch {
    // Column might not exist yet — use fallback
  }

  if (!studioId) {
    studioId = process.env.TWILIO_FALLBACK_STUDIO_ID ?? null
  }

  if (!studioId) {
    logger.warn({ to }, 'twilio-webhook: could not resolve studio from To number — inbound message dropped')
    return
  }

  // ── 2. Try to match client by phone number ─────────────────────────────────
  let clientId: string | null = null

  const { data: clientMatch } = await supabase
    .from('clients')
    .select('id')
    .eq('studio_id', studioId)
    .eq('phone', from)
    .limit(1)
    .single()

  clientId = clientMatch?.id ?? null

  // ── 3. Find or create conversation ────────────────────────────────────────
  const { data: conversationId, error: rpcError } = await supabase.rpc(
    'find_or_create_conversation',
    {
      p_studio_id: studioId,
      p_channel: 'sms',
      p_external_identifier: from,
      p_client_id: clientId,
    },
  )

  if (rpcError || !conversationId) {
    logger.error({ err: rpcError, from, studioId }, 'twilio-webhook: find_or_create_conversation failed')
    return
  }

  // ── 4. Build metadata ─────────────────────────────────────────────────────
  const mediaUrls: string[] = []
  const numMedia = parseInt(params['NumMedia'] ?? '0', 10)
  for (let i = 0; i < numMedia; i++) {
    const url = params[`MediaUrl${i}`]
    if (url) mediaUrls.push(url)
  }

  const metadata: Record<string, unknown> = {
    twilio_message_sid: messageSid,
  }
  if (mediaUrls.length > 0) {
    metadata['media_urls'] = mediaUrls
  }

  // ── 5. Insert inbound comm row ────────────────────────────────────────────
  if (!clientId) {
    // Without a client_id, we can't insert (FK constraint).
    // Log and skip — staff can link the conversation to a client manually.
    logger.warn({ from, studioId, conversationId }, 'twilio-webhook: inbound message from unknown number — no client match; message not stored in client_communications (no FK target)')
    return
  }

  const { error: insertError } = await supabase
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      conversation_id: conversationId as string,
      channel: 'sms',
      direction: 'inbound',
      body,
      status: 'delivered',
      sent_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
      provider_message_id: messageSid,
      metadata: metadata,
    })

  if (insertError) {
    logger.error({ err: insertError, from, messageSid }, 'twilio-webhook: failed to insert inbound comm')
  } else {
    logger.info({ from, studioId, conversationId, messageSid }, 'twilio-webhook: inbound SMS stored')
  }
}

'use server'

/**
 * Messages server actions — all mutations go through here.
 *
 * Each action:
 *  - Resolves studioId from authenticated session
 *  - Validates input with Zod
 *  - Returns { ok, data?, error? }
 *  - Calls revalidatePath where appropriate
 */

import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { sendSmsToClient, sendEmailToClient } from '@/lib/messaging/send'
import {
  markConversationRead,
  assignConversation,
  archiveConversation,
  starConversation,
  linkConversationToClient,
} from '@/lib/messaging/mutations'
import { logger } from '@/lib/logger'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ActionResult<T = undefined> {
  ok: boolean
  data?: T
  error?: string
}

// ─── sendMessageAction ────────────────────────────────────────────────────────

const SendMessageSchema = z.object({
  conversationId: z.string().uuid(),
  clientId: z.string().uuid(),
  body: z.string().min(1).max(1600),
  channel: z.enum(['sms', 'email']),
  subject: z.string().max(200).optional(),
})

export async function sendMessageAction(
  input: z.infer<typeof SendMessageSchema>,
): Promise<ActionResult<{ commId: string }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = SendMessageSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const { conversationId, clientId, body, channel, subject } = parsed.data
  const { studioId } = authUser

  try {
    if (channel === 'sms') {
      const result = await sendSmsToClient(
        { studioId, clientId, body },
        authUser.user.id,
      )
      if (!result.ok) {
        return { ok: false, error: result.error }
      }
      revalidatePath(`/messages/${conversationId}`)
      revalidatePath('/messages')
      return { ok: true, data: { commId: result.commId! } }
    }

    if (channel === 'email') {
      const result = await sendEmailToClient(
        {
          studioId,
          clientId,
          subject: subject ?? '(no subject)',
          body,
        },
        authUser.user.id,
      )
      if (!result.ok) {
        return { ok: false, error: result.error }
      }
      revalidatePath(`/messages/${conversationId}`)
      revalidatePath('/messages')
      return { ok: true, data: { commId: result.commId! } }
    }

    return { ok: false, error: 'Unsupported channel' }
  } catch (err) {
    logger.error({ err, conversationId }, 'sendMessageAction: unexpected error')
    return { ok: false, error: 'Failed to send message' }
  }
}

