'use client'

/**
 * Realtime hooks for the Messages feature.
 *
 * useRealtimeMessages — subscribes to client_communications INSERTs for a
 * single conversation thread. First use of Supabase Realtime in the app.
 *
 * useRealtimeConversationList — subscribes to conversations UPDATEs for the
 * thread list so unread_count + last_message_preview reconcile without reload.
 */

import { useEffect, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { ConversationMessage } from '@/lib/messaging/queries'
import type { Conversation } from '@/lib/supabase/types'

// ─── useRealtimeMessages ──────────────────────────────────────────────────────

export function useRealtimeMessages(
  conversationId: string,
  onNew: (msg: ConversationMessage) => void,
): void {
  // Stable callback ref so useEffect doesn't re-run on every render
  const stableOnNew = useCallback(onNew, [onNew])

  useEffect(() => {
    if (!conversationId) return

    const supabase = createClient()

    const channel = supabase
      .channel(`messages:${conversationId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'client_communications',
          filter: `conversation_id=eq.${conversationId}`,
        },
        (payload) => {
          stableOnNew(payload.new as ConversationMessage)
        },
      )
      .subscribe()

    return () => {
      void supabase.removeChannel(channel)
    }
  }, [conversationId, stableOnNew])
}

// ─── useRealtimeConversationList ──────────────────────────────────────────────

export function useRealtimeConversationList(
  studioId: string,
  onUpdate: (conversation: Conversation) => void,
): void {
  const stableOnUpdate = useCallback(onUpdate, [onUpdate])

  useEffect(() => {
    if (!studioId) return

    const supabase = createClient()

    const channel = supabase
      .channel(`conversations:${studioId}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'conversations',
          filter: `studio_id=eq.${studioId}`,
        },
        (payload) => {
          stableOnUpdate(payload.new as Conversation)
        },
      )
      .subscribe()

    return () => {
      void supabase.removeChannel(channel)
    }
  }, [studioId, stableOnUpdate])
}

'use client'

/**
 * ThreadList — left-rail conversation list.
 *
 * Features:
 * - Search (debounced, searches display_name + external_identifier)
 * - Channel filter pills: All / SMS / Email
 * - Status filter: All / Unread / Starred / Archived
 * - Realtime: conversation UPDATEs reconcile unread_count + preview
 * - Keyboard: j/k navigate, / focus search
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { formatDistanceToNow } from 'date-fns'
import { MessageSquare, Mail, Search, Star, Archive, Inbox } from 'lucide-react'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { useRealtimeConversationList } from '@/hooks/use-realtime-messages'
import type { ConversationWithClient } from '@/lib/messaging/queries'
import type { Conversation, ConversationChannel } from '@/lib/supabase/types'
import { useDebounce } from '@/hooks/useDebounce'

// ─── Types ────────────────────────────────────────────────────────────────────

type StatusFilter = 'all' | 'unread' | 'starred' | 'archived'

interface ThreadListProps {
  conversations: ConversationWithClient[]
  studioId: string
  activeConversationId?: string
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

function getDisplayName(conv: ConversationWithClient): string {
  if (conv.display_name) return conv.display_name
  if (conv.client) {
    const { first_name, last_name } = conv.client
    return last_name ? `${first_name} ${last_name}` : first_name
  }
  return conv.external_identifier
}

function ChannelIcon({ channel, className }: { channel: ConversationChannel; className?: string }) {
  if (channel === 'email') return <Mail className={cn('h-3 w-3', className)} aria-hidden />
  return <MessageSquare className={cn('h-3 w-3', className)} aria-hidden />
}

// ─── ThreadRow ────────────────────────────────────────────────────────────────

function ThreadRow({
  conv,
  isActive,
  onClick,
}: {
  conv: ConversationWithClient
  isActive: boolean
  onClick: () => void
}) {
  const displayName = getDisplayName(conv)
  const initials = getInitials(displayName)
  const hasUnread = conv.unread_count > 0
  const relativeTime = conv.last_message_at
    ? formatDistanceToNow(new Date(conv.last_message_at), { addSuffix: true })
    : null

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'w-full text-left px-3 py-3 flex items-start gap-3 transition-colors rounded-lg',
        'hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
        isActive && 'bg-muted',
      )}
      aria-current={isActive ? 'page' : undefined}
    >
      {/* Avatar */}
      <Avatar className="h-9 w-9 shrink-0 mt-0.5">
        <AvatarFallback className="text-xs font-medium bg-primary/10 text-primary">
          {initials}
        </AvatarFallback>
      </Avatar>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between gap-1 mb-0.5">
          <span className={cn('text-sm truncate', hasUnread ? 'font-semibold text-foreground' : 'font-medium text-foreground/80')}>
            {displayName}
          </span>
          <div className="flex items-center gap-1 shrink-0">
            {conv.starred && <Star className="h-3 w-3 text-amber-400 fill-amber-400" aria-label="Starred" />}
            {relativeTime && (
              <span className="text-[11px] text-muted-foreground whitespace-nowrap">{relativeTime}</span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-1.5">
          <ChannelIcon channel={conv.channel} className="text-muted-foreground shrink-0" />
          <p className={cn('text-xs truncate flex-1', hasUnread ? 'text-foreground/80' : 'text-muted-foreground')}>
            {conv.last_message_preview ?? conv.external_identifier}
          </p>
          {hasUnread && (
            <Badge
              variant="default"
              className="h-4 min-w-4 px-1 text-[10px] font-bold shrink-0 rounded-full"
            >
              {conv.unread_count > 99 ? '99+' : conv.unread_count}
            </Badge>
          )}
        </div>
      </div>
    </button>
  )
}

// ─── ThreadList ───────────────────────────────────────────────────────────────

export function ThreadList({ conversations: initialConversations, studioId, activeConversationId }: ThreadListProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchInputRef = useRef<HTMLInputElement>(null)

  const [convs, setConvs] = useState<ConversationWithClient[]>(initialConversations)
  const [searchRaw, setSearchRaw] = useState('')
  const [channelFilter, setChannelFilter] = useState<ConversationChannel | 'all'>('all')
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all')
  const [activeIndex, setActiveIndex] = useState<number>(-1)

  const search = useDebounce(searchRaw, 300)

  // Realtime reconciliation
  const handleConversationUpdate = useCallback((updated: Conversation) => {
    setConvs((prev) =>
      prev
        .map((c) =>
          c.id === updated.id
            ? { ...c, ...updated }
            : c,
        )
        .sort((a, b) => {
          const aTime = a.last_message_at ?? a.created_at
          const bTime = b.last_message_at ?? b.created_at
          return new Date(bTime).getTime() - new Date(aTime).getTime()
        }),
    )
  }, [])

  useRealtimeConversationList(studioId, handleConversationUpdate)

  // Keep local state in sync when server re-renders
  useEffect(() => {
    setConvs(initialConversations)
  }, [initialConversations])

  // ── Keyboard navigation ──────────────────────────────────────────────────
  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      const tag = (e.target as HTMLElement).tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA') {
        if (e.key === 'Escape') {
          searchInputRef.current?.blur()
        }
        return
      }

      if (e.key === '/') {
        e.preventDefault()
        searchInputRef.current?.focus()
        return
      }

      if (e.key === 'j') {
        setActiveIndex((i) => Math.min(i + 1, filtered.length - 1))
      } else if (e.key === 'k') {
        setActiveIndex((i) => Math.max(i - 1, 0))
      } else if (e.key === 'Enter' && activeIndex >= 0) {
        const conv = filtered[activeIndex]
        if (conv) {
          router.push(`/messages/${conv.id}`)
        }
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeIndex])

  // ── Filter logic ──────────────────────────────────────────────────────────
  const filtered = convs.filter((c) => {
    if (channelFilter !== 'all' && c.channel !== channelFilter) return false

    if (statusFilter === 'unread' && c.unread_count === 0) return false
    if (statusFilter === 'starred' && !c.starred) return false
    if (statusFilter === 'archived' && !c.archived_at) return false
    if (statusFilter !== 'archived' && c.archived_at) return false

    if (search) {
      const q = search.toLowerCase()
      const name = getDisplayName(c).toLowerCase()
      const ext = c.external_identifier.toLowerCase()
      if (!name.includes(q) && !ext.includes(q)) return false
    }

    return true
  })

  const channelButtons: { value: ConversationChannel | 'all'; label: string }[] = [
    { value: 'all', label: 'All' },
    { value: 'sms', label: 'SMS' },
    { value: 'email', label: 'Email' },
  ]

  const statusButtons: { value: StatusFilter; label: string; icon: React.ReactNode }[] = [
    { value: 'all', label: 'All', icon: <Inbox className="h-3 w-3" /> },
    { value: 'unread', label: 'Unread', icon: null },
    { value: 'starred', label: 'Starred', icon: <Star className="h-3 w-3" /> },
    { value: 'archived', label: 'Archived', icon: <Archive className="h-3 w-3" /> },
  ]

  return (
    <div className="flex flex-col h-full">
      {/* Search */}
      <div className="px-3 pt-3 pb-2">
        <div className="relative">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
          <Input
            ref={searchInputRef}
            placeholder="Search messages… (/)"
            value={searchRaw}
            onChange={(e) => setSearchRaw(e.target.value)}
            className="pl-8 h-8 text-sm"
            aria-label="Search conversations"
          />
        </div>
      </div>

      {/* Channel filter pills */}
      <div className="px-3 pb-2 flex gap-1">
        {channelButtons.map((btn) => (
          <button
            key={btn.value}
            type="button"
            onClick={() => setChannelFilter(btn.value)}
            className={cn(
              'px-2.5 py-1 rounded-full text-xs font-medium transition-colors',
              channelFilter === btn.value
                ? 'bg-primary text-primary-foreground'
                : 'bg-muted text-muted-foreground hover:bg-muted/80',
            )}
          >
            {btn.label}
          </button>
        ))}
      </div>

      {/* Status filter */}
      <div className="px-3 pb-2 flex gap-1 flex-wrap">
        {statusButtons.map((btn) => (
          <button
            key={btn.value}
            type="button"
            onClick={() => setStatusFilter(btn.value)}
            className={cn(
              'flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium transition-colors',
              statusFilter === btn.value
                ? 'bg-primary/10 text-primary border border-primary/20'
                : 'text-muted-foreground hover:text-foreground',
            )}
          >
            {btn.icon}
            {btn.label}
          </button>
        ))}
      </div>

      {/* Thread list */}
      <div
        className="flex-1 overflow-y-auto px-2 pb-3 space-y-0.5"
        role="listbox"
        aria-label="Conversations"
      >
        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
            <MessageSquare className="h-8 w-8 text-muted-foreground/40 mb-3" aria-hidden />
            <p className="text-sm font-medium text-muted-foreground">No conversations</p>
            <p className="text-xs text-muted-foreground/60 mt-1">
              {search ? 'Try a different search' : 'Messages from clients will appear here'}
            </p>
          </div>
        ) : (
          filtered.map((conv, i) => (
            <ThreadRow
              key={conv.id}
              conv={conv}
              isActive={
                conv.id === activeConversationId ||
                pathname === `/messages/${conv.id}` ||
                i === activeIndex
              }
              onClick={() => router.push(`/messages/${conv.id}`)}
            />
          ))
