'use client'

/**
 * Composer — message compose area at the bottom of ThreadPanel.
 *
 * Features:
 * - Auto-growing textarea (max 10 rows)
 * - Channel indicator (matches conversation channel)
 * - Template picker (fills textarea with template body)
 * - Optimistic send: message appears immediately, reconciled via Realtime
 * - Keyboard: Cmd+Enter to send
 */

import { useState, useRef, useCallback, useTransition } from 'react'
import { Send, ChevronDown, MessageSquare, Mail, Sparkles } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { cn } from '@/lib/utils'
import { sendMessageAction } from '@/app/(app)/messages/actions'
import type { ConversationMessage } from '@/lib/messaging/queries'
import type { ConversationChannel } from '@/lib/supabase/types'

// ─── SMS templates ────────────────────────────────────────────────────────────

interface MessageTemplate {
  label: string
  body: string
  channel: 'sms' | 'email' | 'both'
}

const MESSAGE_TEMPLATES: MessageTemplate[] = [
  {
    label: 'Appointment reminder',
    body: 'Hi {{clientFirstName}}, just a reminder about your appointment tomorrow. See you then!',
    channel: 'both',
  },
  {
    label: 'Deposit request',
    body: 'Hi {{clientFirstName}}, to hold your spot we require a deposit. You can pay here: {{depositLink}}',
    channel: 'both',
  },
  {
    label: 'Aftercare instructions',
    body: 'Hi {{clientFirstName}}, here are your aftercare instructions: Keep it clean, moisturized, and out of the sun for 2 weeks.',
    channel: 'both',
  },
  {
    label: 'Follow-up check-in',
    body: "Hi {{clientFirstName}}, just checking in on how your piece is healing. Any questions, don't hesitate to reach out!",
    channel: 'both',
  },
  {
    label: 'Booking confirmation',
    body: 'Hi {{clientFirstName}}, your booking is confirmed! Looking forward to seeing you.',
    channel: 'both',
  },
]

// ─── Types ────────────────────────────────────────────────────────────────────

interface ComposerProps {
  conversationId: string
  clientId: string
  channel: ConversationChannel
  clientFirstName?: string
  onOptimisticSend: (msg: ConversationMessage) => void
  disabled?: boolean
}

// ─── Composer ─────────────────────────────────────────────────────────────────

export function Composer({
  conversationId,
  clientId,
  channel,
  clientFirstName = 'Client',
  onOptimisticSend,
  disabled = false,
}: ComposerProps) {
  const [body, setBody] = useState('')
  const [isPending, startTransition] = useTransition()
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  const isSmsSuitable = channel === 'sms'
  const isEmailSuitable = channel === 'email'

  // Auto-resize textarea
  const handleChange = useCallback((e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setBody(e.target.value)
    const el = e.target
    el.style.height = 'auto'
    el.style.height = `${Math.min(el.scrollHeight, 240)}px`
  }, [])

  const applyTemplate = useCallback(
    (template: MessageTemplate) => {
      const filled = template.body
        .replace(/\{\{clientFirstName\}\}/g, clientFirstName)
        .replace(/\{\{depositLink\}\}/g, '[deposit link]')

      setBody(filled)
      setTimeout(() => {
        const el = textareaRef.current
        if (el) {
          el.focus()
          el.style.height = 'auto'
          el.style.height = `${Math.min(el.scrollHeight, 240)}px`
          el.setSelectionRange(filled.length, filled.length)
        }
      }, 0)
    },
    [clientFirstName],
  )

  const handleSend = useCallback(() => {
    const trimmed = body.trim()
    if (!trimmed || isPending || disabled) return

    // Optimistic: add message to UI immediately
    const optimisticMsg: ConversationMessage = {
      id: `optimistic-${Date.now()}`,
      conversation_id: conversationId,
      channel: channel as 'email' | 'sms' | 'whatsapp' | 'in_app',
      direction: 'outbound',
      subject: null,
      body: trimmed,
      status: 'queued',
      sent_at: null,
      delivered_at: null,
      opened_at: null,
      error: null,
      provider_message_id: null,
      metadata: {},
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }

    onOptimisticSend(optimisticMsg)
    setBody('')
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
    }

    startTransition(async () => {
      const result = await sendMessageAction({
        conversationId,
        clientId,
        body: trimmed,
        channel: channel === 'sms' ? 'sms' : 'email',
      })

      if (!result.ok) {
        toast.error(result.error ?? 'Failed to send message')
      }
    })
  }, [body, isPending, disabled, conversationId, clientId, channel, onOptimisticSend])

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
        e.preventDefault()
        handleSend()
      }
    },
    [handleSend],
  )

  const canSend = body.trim().length > 0 && !isPending && !disabled
  const filteredTemplates = MESSAGE_TEMPLATES.filter(
    (t) => t.channel === 'both' || t.channel === channel,
  )

  return (
    <div className="border-t border-border bg-background px-4 py-3">
      {/* Channel indicator */}
      <div className="flex items-center gap-1.5 mb-2">
        {isSmsSuitable ? (
          <MessageSquare className="h-3.5 w-3.5 text-muted-foreground" aria-hidden />
        ) : (
          <Mail className="h-3.5 w-3.5 text-muted-foreground" aria-hidden />
        )}
        <span className="text-xs text-muted-foreground font-medium">
          {isSmsSuitable ? 'SMS' : isEmailSuitable ? 'Email' : 'Message'}
        </span>
        {isSmsSuitable && body.length > 0 && (
          <span className={cn('ml-auto text-[10px]', body.length > 160 ? 'text-amber-500' : 'text-muted-foreground/60')}>
            {body.length} char{body.length > 160 ? ` (${Math.ceil(body.length / 160)} segments)` : ''}
          </span>
        )}
      </div>

      {/* Textarea */}
      <div className="relative">
        <textarea
          ref={textareaRef}
          value={body}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          placeholder={`Type a ${isSmsSuitable ? 'message' : 'email'}… (${typeof navigator !== 'undefined' && navigator.platform?.toLowerCase().includes('mac') ? '⌘' : 'Ctrl'}+Enter to send)`}
          rows={2}
          disabled={disabled || isPending}
          aria-label="Message body"
          className={cn(
            'w-full resize-none rounded-lg border border-input bg-background px-3 py-2 text-sm',
            'placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
            'disabled:opacity-50 disabled:cursor-not-allowed',
            'min-h-[64px] max-h-[240px] overflow-y-auto',
          )}
          style={{ height: 'auto' }}
        />
      </div>

      {/* Actions row */}
      <div className="flex items-center justify-between mt-2">
        {/* Template picker */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              className="h-7 px-2 text-xs text-muted-foreground"
              disabled={disabled}
            >
              <Sparkles className="h-3 w-3 mr-1" />
              Templates
              <ChevronDown className="h-3 w-3 ml-1" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" className="w-56">
            <DropdownMenuLabel className="text-xs">Quick templates</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {filteredTemplates.map((template) => (
              <DropdownMenuItem
                key={template.label}
                onClick={() => applyTemplate(template)}
                className="text-xs"
              >
                {template.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>

        {/* Send button */}
        <Button
          size="sm"
          className="h-7 px-3 text-xs"
          disabled={!canSend}
          onClick={handleSend}
        >
          {isPending ? (
            <span className="animate-pulse">Sending…</span>
          ) : (
            <>
              <Send className="h-3 w-3 mr-1.5" aria-hidden />
              Send
            </>
          )}
        </Button>
      </div>
    </div>
  )
}

'use client'

/**
 * ThreadPanel — active conversation view.
 *
 * Renders message bubbles grouped by day, with a Composer at the bottom.
 * Subscribes to Realtime inserts so new messages appear without reload.
 * Optimistic UI: outbound messages appear immediately before server confirms.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { format, isToday, isYesterday, isSameDay } from 'date-fns'
import {
  ChevronLeft,
  MoreHorizontal,
  Star,
  Archive,
  UserPlus,
  User,
  ExternalLink,
  MessageSquare,
  Mail,
  CheckCircle2,
  Clock,
  XCircle,
  Send,
} from 'lucide-react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Separator } from '@/components/ui/separator'
import { cn } from '@/lib/utils'
import { Composer } from './Composer'
import { ClientContextCard } from './ClientContextCard'
import { useRealtimeMessages } from '@/hooks/use-realtime-messages'
import { archiveAction, starAction, markReadAction } from '@/app/(app)/messages/actions'
import type { ConversationWithClient, ConversationMessage, ClientBookingSummary } from '@/lib/messaging/queries'

// ─── Types ────────────────────────────────────────────────────────────────────

interface ThreadPanelProps {
  conversation: ConversationWithClient
  initialMessages: ConversationMessage[]
  recentBookings?: ClientBookingSummary[]
  showBackButton?: boolean
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getDayLabel(dateStr: string): string {
  const d = new Date(dateStr)
  if (isToday(d)) return 'Today'
  if (isYesterday(d)) return 'Yesterday'
  return format(d, 'MMMM d, yyyy')
}

function getStatusIcon(status: ConversationMessage['status']) {
  switch (status) {
    case 'queued':
      return <Clock className="h-3 w-3 text-muted-foreground/50" aria-label="Queued" />
    case 'sent':
      return <Send className="h-3 w-3 text-muted-foreground/60" aria-label="Sent" />
    case 'delivered':
    case 'opened':
    case 'clicked':
      return <CheckCircle2 className="h-3 w-3 text-emerald-500" aria-label="Delivered" />
    case 'failed':
    case 'bounced':
      return <XCircle className="h-3 w-3 text-destructive" aria-label="Failed" />
    default:
      return null
  }
}

function getChannelIcon(channel: ConversationMessage['channel']) {
  if (channel === 'email') return <Mail className="h-3 w-3" />
  return <MessageSquare className="h-3 w-3" />
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

// ─── MessageBubble ────────────────────────────────────────────────────────────

function MessageBubble({ msg }: { msg: ConversationMessage }) {
  const isOutbound = msg.direction === 'outbound'
  const isOptimistic = msg.id.startsWith('optimistic-')

  return (
    <div className={cn('flex gap-2 group', isOutbound ? 'justify-end' : 'justify-start')}>
      {!isOutbound && (
        <Avatar className="h-6 w-6 shrink-0 mt-1">
          <AvatarFallback className="text-[9px] bg-muted text-muted-foreground">C</AvatarFallback>
        </Avatar>
      )}

      <div className={cn('max-w-[75%] space-y-1', isOutbound && 'items-end flex flex-col')}>
        {/* Subject line for emails */}
        {msg.subject && (
          <p className="text-[10px] font-medium text-muted-foreground uppercase tracking-wide">
            {msg.subject}
          </p>
        )}

        <div
          className={cn(
            'px-3 py-2 rounded-2xl text-sm',
            isOutbound
              ? 'bg-primary text-primary-foreground rounded-tr-sm'
              : 'bg-muted text-foreground rounded-tl-sm',
            isOptimistic && 'opacity-60',
          )}
        >
          <p className="whitespace-pre-wrap break-words">{msg.body}</p>
        </div>

        {/* Timestamp + status */}
        <div className={cn('flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity', isOutbound && 'flex-row-reverse')}>
          <span className="text-[10px] text-muted-foreground">
            {format(new Date(msg.created_at), 'h:mm a')}
          </span>
          {isOutbound && getStatusIcon(msg.status)}
          {msg.status === 'failed' && msg.error && (
            <span className="text-[10px] text-destructive">{msg.error}</span>
          )}
        </div>
      </div>
    </div>
  )
}

// ─── ThreadPanel ──────────────────────────────────────────────────────────────

export function ThreadPanel({
  conversation,
  initialMessages,
  recentBookings = [],
  showBackButton = false,
}: ThreadPanelProps) {
  const router = useRouter()
  const [messages, setMessages] = useState<ConversationMessage[]>(initialMessages)
  const [showClientSidebar, setShowClientSidebar] = useState(true)
  const messagesEndRef = useRef<HTMLDivElement>(null)

  const client = conversation.client
  const clientName = client
    ? [client.first_name, client.last_name].filter(Boolean).join(' ')
    : conversation.display_name ?? conversation.external_identifier

  // Auto-scroll to bottom when messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages.length])

  // Sync messages when prop changes (navigation)
  useEffect(() => {
    setMessages(initialMessages)
  }, [initialMessages])

  // Realtime: append new inbound messages
  const handleNewMessage = useCallback((msg: ConversationMessage) => {
    setMessages((prev) => {
      // Remove matching optimistic message if it's now confirmed
      const withoutOptimistic = prev.filter((m) => {
        if (!m.id.startsWith('optimistic-')) return true
        // Match by body + direction + created within last 30s
        return !(
          m.body === msg.body &&
          m.direction === msg.direction &&
          Math.abs(new Date(m.created_at).getTime() - new Date(msg.created_at).getTime()) < 30_000
        )
      })

      // Don't add duplicate real messages
      if (withoutOptimistic.some((m) => m.id === msg.id)) return withoutOptimistic

      return [...withoutOptimistic, msg]
    })
  }, [])

  useRealtimeMessages(conversation.id, handleNewMessage)

  // Optimistic send handler (from Composer)
  const handleOptimisticSend = useCallback((msg: ConversationMessage) => {
    setMessages((prev) => [...prev, msg])
  }, [])

  // Quick actions
  const handleArchive = useCallback(async () => {
    const result = await archiveAction(conversation.id)
    if (result.ok) {
      toast.success('Conversation archived')
      router.push('/messages')
    } else {
      toast.error(result.error ?? 'Failed to archive')
    }
  }, [conversation.id, router])

  const handleStar = useCallback(async () => {
    const result = await starAction(conversation.id, !conversation.starred)
    if (result.ok) {
      toast.success(conversation.starred ? 'Removed from starred' : 'Starred')
    } else {
      toast.error(result.error ?? 'Failed')
    }
  }, [conversation.id, conversation.starred])

  // Group messages by day
  const messageGroups: { dayLabel: string; date: Date; messages: ConversationMessage[] }[] = []
  for (const msg of messages) {
    const d = new Date(msg.created_at)
    const last = messageGroups[messageGroups.length - 1]
    if (!last || !isSameDay(last.date, d)) {
      messageGroups.push({ dayLabel: getDayLabel(msg.created_at), date: d, messages: [msg] })
    } else {
      last.messages.push(msg)
    }
  }

  return (
    <div className="flex h-full overflow-hidden">
      {/* Main thread column */}
      <div className="flex flex-col flex-1 min-w-0">
        {/* Header */}
        <div className="flex items-center gap-2 px-4 py-3 border-b border-border bg-background shrink-0">
          {showBackButton && (
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0 mr-1"
              onClick={() => router.push('/messages')}
              aria-label="Back to conversations"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
          )}

          <Avatar className="h-8 w-8 shrink-0">
            <AvatarFallback className="bg-primary/10 text-primary text-xs font-medium">
              {getInitials(clientName)}
            </AvatarFallback>
          </Avatar>

          <div className="flex-1 min-w-0">
            <p className="font-semibold text-sm text-foreground truncate">{clientName}</p>
            <div className="flex items-center gap-1">
              {getChannelIcon(conversation.channel as ConversationMessage['channel'])}
              <span className="text-[10px] text-muted-foreground capitalize">{conversation.channel}</span>
              {conversation.assigned_to && (
                <Badge variant="outline" className="text-[9px] h-4 px-1 ml-1">Assigned</Badge>
              )}
            </div>
          </div>

          {/* Quick actions */}
          <div className="flex items-center gap-1 shrink-0">
            {client && (
              <Link href={`/clients/${client.id}`}>
                <Button variant="ghost" size="sm" className="h-7 w-7 p-0 hidden sm:flex" aria-label="View client profile">
                  <ExternalLink className="h-3.5 w-3.5" />
                </Button>
              </Link>
            )}
            <Button
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0"
              aria-label={showClientSidebar ? 'Hide client info' : 'Show client info'}
              onClick={() => setShowClientSidebar((v) => !v)}
            >
              <User className="h-3.5 w-3.5" />
            </Button>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="h-7 w-7 p-0" aria-label="More actions">
                  <MoreHorizontal className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-44">
                <DropdownMenuItem
                  onClick={() => void handleStar()}
                  className="text-xs"
                >
                  <Star className={cn('h-3.5 w-3.5 mr-2', conversation.starred && 'fill-amber-400 text-amber-400')} />
                  {conversation.starred ? 'Unstar' : 'Star'}
                </DropdownMenuItem>
                {client && (
                  <DropdownMenuItem asChild className="text-xs">
                    <Link href={`/clients/${client.id}`}>
                      <User className="h-3.5 w-3.5 mr-2" />
                      View client
                    </Link>
                  </DropdownMenuItem>
                )}
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  onClick={() => void handleArchive()}
                  className="text-xs text-muted-foreground"
                >
                  <Archive className="h-3.5 w-3.5 mr-2" />
                  Archive
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>

        {/* Messages area */}
        <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center py-12">
              <MessageSquare className="h-10 w-10 text-muted-foreground/30 mb-3" aria-hidden />
              <p className="text-sm font-medium text-muted-foreground">No messages yet</p>
              <p className="text-xs text-muted-foreground/60 mt-1">Start the conversation below</p>
            </div>
          ) : (
            messageGroups.map((group) => (
              <div key={group.dayLabel} className="space-y-3">
                {/* Day separator */}
                <div className="flex items-center gap-3">
                  <Separator className="flex-1" />
                  <span className="text-[10px] text-muted-foreground font-medium whitespace-nowrap px-1">
                    {group.dayLabel}
                  </span>
                  <Separator className="flex-1" />
                </div>

                {/* Messages in this day */}
                <div className="space-y-2">
                  {group.messages.map((msg) => (
                    <MessageBubble key={msg.id} msg={msg} />
                  ))}
                </div>
              </div>
            ))
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Composer */}
        <Composer
          conversationId={conversation.id}
          clientId={client?.id ?? ''}
          channel={conversation.channel}
