'use client'

/**
 * MessagesShell — 2-pane layout wrapper.
 *
 * Desktop: left rail (360px threads) + right (thread panel + client sidebar)
 * Mobile: thread list is default view; tapping a thread navigates to /messages/[id]
 *
 * This component is "use client" only for the isMobile detection;
 * both children are server-rendered (passed as props).
 */

import { cn } from '@/lib/utils'
import { useIsMobile } from '@/hooks/useIsMobile'
import type { ConversationWithClient, ConversationMessage, ClientBookingSummary } from '@/lib/messaging/queries'
import { ThreadList } from './ThreadList'
import { ThreadPanel } from './ThreadPanel'
import { MessageSquare } from 'lucide-react'

// ─── Types ────────────────────────────────────────────────────────────────────

interface MessagesShellProps {
  conversations: ConversationWithClient[]
  activeConversation?: ConversationWithClient | null
  activeMessages?: ConversationMessage[]
  recentBookings?: ClientBookingSummary[]
  studioId: string
  activeConversationId?: string
}

// ─── MessagesShell ────────────────────────────────────────────────────────────

export function MessagesShell({
  conversations,
  activeConversation,
  activeMessages = [],
  recentBookings = [],
  studioId,
  activeConversationId,
}: MessagesShellProps) {
  const isMobile = useIsMobile()

  // On mobile: if we have an active conversation, show only the thread panel
  if (isMobile && activeConversation) {
    return (
      <div className="h-full">
        <ThreadPanel
          conversation={activeConversation}
          initialMessages={activeMessages}
          recentBookings={recentBookings}
          showBackButton
        />
      </div>
    )
  }

  // On mobile without active conversation: show only thread list
  if (isMobile) {
    return (
      <div className="h-full">
        <ThreadList
          conversations={conversations}
          studioId={studioId}
          activeConversationId={activeConversationId}
        />
      </div>
    )
  }

  // Desktop: 2-pane layout
  return (
    <div className="flex h-full overflow-hidden">
      {/* Left rail — thread list */}
      <div className="w-[360px] shrink-0 border-r border-border flex flex-col overflow-hidden">
        <ThreadList
          conversations={conversations}
          studioId={studioId}
          activeConversationId={activeConversationId}
        />
      </div>

      {/* Right — thread panel or empty state */}
      <div className="flex-1 min-w-0 overflow-hidden">
        {activeConversation ? (
          <ThreadPanel
            conversation={activeConversation}
            initialMessages={activeMessages}
            recentBookings={recentBookings}
          />
        ) : (
          <EmptyThreadState hasConversations={conversations.length > 0} />
        )}
      </div>
    </div>
  )
}

// ─── EmptyThreadState ─────────────────────────────────────────────────────────

function EmptyThreadState({ hasConversations }: { hasConversations: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center h-full text-center px-8">
      <div className="h-14 w-14 rounded-2xl bg-primary/10 flex items-center justify-center mb-4">
        <MessageSquare className="h-7 w-7 text-primary" aria-hidden />
      </div>
      <h2 className="font-semibold text-foreground mb-1">
        {hasConversations ? 'Select a conversation' : 'No messages yet'}
      </h2>
      <p className="text-sm text-muted-foreground max-w-xs">
        {hasConversations
          ? 'Choose a conversation from the left to view messages.'
          : 'When clients message you via SMS or email, their conversations will appear here.'}
      </p>
    </div>
  )
}

import type { Metadata } from 'next'
