export default async function MessagesPage() {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  // Fetch conversation list
  const { conversations } = await listConversations(studioId, {
    limit: 50,
    archived: false,
  })

  // Auto-select first conversation on desktop (pre-fetch its messages)
  const firstConv = conversations[0] ?? null
  const [firstMessages, firstBookings] = firstConv
    ? await Promise.all([
        getConversationMessages(studioId, firstConv.id, { limit: 50 }),
        firstConv.client
          ? getClientBookingsSummary(studioId, firstConv.client.id, 3)
          : Promise.resolve([]),
      ])
    : [[], []]

  // Mark first conversation as read on page load
  if (firstConv && firstConv.unread_count > 0) {
    await markConversationRead(studioId, firstConv.id)
  }

  return (
    <div className="h-[calc(100vh-4rem)] overflow-hidden">
      <MessagesShell
        conversations={conversations}
        activeConversation={firstConv}
        activeMessages={firstMessages}
        recentBookings={firstBookings}
        studioId={studioId}
        activeConversationId={firstConv?.id}
      />
    </div>
  )
}

import type { Metadata } from 'next'
import { notFound, redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import {
  listConversations,
  getConversation,
  getConversationMessages,
  getClientBookingsSummary,
} from '@/lib/messaging/queries'
import { markConversationRead } from '@/lib/messaging/mutations'
import { MessagesShell } from '@/components/messages/MessagesShell'

export const metadata: Metadata = {
  title: 'Messages — InkOS',
}

interface ConversationPageProps {
  params: Promise<{ conversationId: string }>
}

export default async function ConversationPage({ params }: ConversationPageProps) {
  const { conversationId } = await params

  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  // Fetch all data in parallel
  const [{ conversations }, activeConversation] = await Promise.all([
    listConversations(studioId, { limit: 50, archived: false }),
    getConversation(studioId, conversationId),
  ])

  if (!activeConversation) {
    notFound()
  }

  const [messages, recentBookings] = await Promise.all([
    getConversationMessages(studioId, conversationId, { limit: 50 }),
    activeConversation.client
      ? getClientBookingsSummary(studioId, activeConversation.client.id, 3)
      : Promise.resolve([]),
  ])

  // Mark as read
  if (activeConversation.unread_count > 0) {
    await markConversationRead(studioId, conversationId)
  }

  return (
    <div className="h-[calc(100vh-4rem)] overflow-hidden">
      <MessagesShell
        conversations={conversations}
        activeConversation={activeConversation}
        activeMessages={messages}
        recentBookings={recentBookings}
        studioId={studioId}
        activeConversationId={conversationId}
      />
    </div>
  )
}

